package com.skillbridge;
import com.fasterxml.jackson.databind.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") @Transactional
class AdminController {
 final WorkspaceService w;final JdbcTemplate db;AdminController(WorkspaceService w){this.w=w;db=w.db();}
 @GetMapping("/users") Object users(@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String role,@RequestParam(defaultValue="0")int page){return db.queryForList("SELECT id,name,email,role,enabled,verified,created_at FROM app_user WHERE (name ILIKE ? OR email ILIKE ?) AND (?='' OR role=?) ORDER BY id LIMIT 10 OFFSET ?","%"+q+"%","%"+q+"%",role,role,Math.max(0,page)*10);}
 @PatchMapping("/users/{id}") Object editUser(Authentication a,@PathVariable long id,@RequestBody JsonNode b){var actor=SecurityConfig.member(a);var rows=db.queryForList("SELECT id,role FROM app_user WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.error(404,"User not found.");if(id==actor.id()&&(b.has("role")&&!b.path("role").asText().equals(actor.role())||b.has("enabled")&&!b.path("enabled").asBoolean()))throw ApiException.error(400,"Use another administrator to change your own access.");if(b.has("name")){String name=WorkspaceService.text(b,"name",2,80);db.update("UPDATE app_user SET name=? WHERE id=?",name,id);db.update("UPDATE mentor_profile SET name=? WHERE user_id=?",name,id);w.patch(id,state->state.put("name",name));}if(b.has("role")){String role=WorkspaceService.text(b,"role",1,16);if(!List.of("LEARNER","MENTOR","ADMIN").contains(role))throw ApiException.error(400,"Choose a valid role.");db.update("UPDATE app_user SET role=? WHERE id=?",role,id);if(!role.equals("MENTOR"))db.update("UPDATE mentor_profile SET approved=false WHERE user_id=?",id);}if(b.has("enabled"))db.update("UPDATE app_user SET enabled=? WHERE id=?",b.path("enabled").asBoolean(),id);db.update("DELETE FROM auth_token WHERE user_id=?",id);w.audit(actor.id(),"user.update",String.valueOf(id),b);return Map.of("message","User updated; active sessions revoked.");}
 @GetMapping("/mentors") Object mentors(){var rows=db.queryForList("SELECT * FROM mentor_profile ORDER BY id");for(var row:rows){long id=((Number)row.get("id")).longValue();row.put("slots",db.query("SELECT starts_at FROM mentor_slot WHERE mentor_id=? AND starts_at>now() ORDER BY starts_at",(rs,n)->rs.getTimestamp(1).toInstant().toString(),id));}return rows;}
 @PatchMapping("/mentors/{id}") Object editMentor(Authentication a,@PathVariable long id,@RequestBody JsonNode b){var rows=db.queryForList("SELECT * FROM mentor_profile WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.error(404,"Mentor not found.");var old=rows.get(0);String name=WorkspaceService.text(b,"name",2,80),expertise=WorkspaceService.text(b,"expertise",2,500),bio=WorkspaceService.text(b,"bio",2,3000),language=WorkspaceService.text(b,"language",2,80);double price=b.path("price").asDouble(-1);if(!Double.isFinite(price)||price<0||price>1000)throw ApiException.error(400,"Choose a price from 0 to 1000.");boolean approved=b.path("approved").asBoolean();if(approved&&old.get("user_id")!=null&&db.queryForObject("SELECT count(*) FROM app_user WHERE id=? AND role='MENTOR' AND enabled",Long.class,old.get("user_id"))==0)throw ApiException.error(400,"An approved mentor needs an active mentor account. Update the member role first.");if(!b.path("slots").isArray()||b.path("slots").size()>100)throw ApiException.error(400,"Provide up to 100 future times.");var slots=new ArrayList<java.time.Instant>();for(var value:b.path("slots")){try{var time=java.time.Instant.parse(value.asText());if(!time.isAfter(java.time.Instant.now()))throw new IllegalArgumentException();slots.add(time);}catch(Exception e){throw ApiException.error(400,"Use future ISO timestamps for availability.");}}db.update("UPDATE mentor_profile SET name=?,expertise=?,bio=?,language=?,price=?,approved=? WHERE id=?",name,expertise,bio,language,price,approved,id);db.update("DELETE FROM mentor_slot WHERE mentor_id=?",id);for(var time:slots)db.update("INSERT INTO mentor_slot VALUES(?,?) ON CONFLICT DO NOTHING",id,java.sql.Timestamp.from(time));if(old.get("user_id")!=null){long user=((Number)old.get("user_id")).longValue();db.update("UPDATE app_user SET name=? WHERE id=?",name,user);w.patch(user,state->{state.put("name",name);state.put("mentorPrice",price);state.set("availability",b.get("slots"));});}w.audit(SecurityConfig.member(a).id(),"mentor.update",String.valueOf(id),b);return Map.of("message","Mentor profile updated.");}
 @GetMapping("/applications") Object applications(){var rows=db.queryForList("SELECT a.*,u.email FROM mentor_application a JOIN app_user u ON u.id=a.user_id ORDER BY a.created_at DESC");for(var row:rows)row.put("data",w.object(row.get("data").toString()));return rows;}
 @PostMapping("/applications/decision") Object decision(Authentication a,@RequestBody JsonNode b){var actor=SecurityConfig.member(a);long id=b.path("applicationId").asLong();var apps=db.queryForList("SELECT * FROM mentor_application WHERE id=? FOR UPDATE",id);if(apps.isEmpty())throw ApiException.error(404,"Application not found.");String status=WorkspaceService.text(b,"status",1,40),decision=WorkspaceService.text(b,"decision",10,2000);if(!List.of("Approved","Rejected","More information requested").contains(status))throw ApiException.error(400,"Choose a valid decision.");var app=apps.get(0);long user=((Number)app.get("user_id")).longValue();var data=w.object(app.get("data").toString());db.update("UPDATE mentor_application SET status=?,decision=?,reviewed_by=?,reviewed_at=now() WHERE id=?",status,decision,actor.id(),id);if(status.equals("Approved")){db.update("UPDATE app_user SET role='MENTOR' WHERE id=? AND role<>'ADMIN'",user);db.update("INSERT INTO mentor_profile(user_id,name,expertise,bio,price,approved) VALUES(?,?,?,?,45,true) ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,expertise=excluded.expertise,bio=excluded.bio,approved=true",user,data.path("name").asText(),data.path("expertise").asText(),data.path("experience").asText());}else db.update("UPDATE mentor_profile SET approved=false WHERE user_id=?",user);db.update("DELETE FROM auth_token WHERE user_id=?",user);w.note(user,"Your mentor application: "+status+". "+decision);w.audit(actor.id(),"mentor.review",String.valueOf(id),Map.of("status",status,"decision",decision));return w.state(actor);}
 @GetMapping("/content") Object content(){var rows=db.queryForList("SELECT * FROM content ORDER BY id");for(var row:rows)row.put("data",w.object(row.get("data").toString()));return rows;}
 @PostMapping("/content") Object create(Authentication a,@RequestBody JsonNode b){String type=WorkspaceService.text(b,"type",1,20),title=WorkspaceService.text(b,"title",2,150),description=WorkspaceService.text(b,"description",1,10000);if(!List.of("Course","Project","Lesson","Category","Skill").contains(type))throw ApiException.error(400,"Choose a valid content type.");Long id=db.queryForObject("INSERT INTO content(kind,title,description) VALUES(?,?,?) RETURNING id",Long.class,type,title,description);var data=b.path("data").isObject()?(com.fasterxml.jackson.databind.node.ObjectNode)b.get("data").deepCopy():w.json().createObjectNode();data.put("id",id);data.put("title",title);db.update("UPDATE content SET data=?::jsonb WHERE id=?",w.encode(data),id);w.audit(SecurityConfig.member(a).id(),"content.create",String.valueOf(id),Map.of("type",type));return Map.of("id",id,"status","Draft");}
 @PatchMapping("/content/{id}") Object editContent(Authentication a,@PathVariable long id,@RequestBody JsonNode b){var rows=db.queryForList("SELECT * FROM content WHERE id=? FOR UPDATE",id);if(rows.isEmpty())throw ApiException.error(404,"Content not found.");var old=rows.get(0);String title=b.has("title")?WorkspaceService.text(b,"title",2,150):old.get("title").toString();String status=b.path("status").asText(old.get("status").toString());if(!List.of("Draft","Published","Archived").contains(status))throw ApiException.error(400,"Invalid content status.");if(b.has("data")&&!b.path("data").isObject())throw ApiException.error(400,"Content data must be an object.");var data=b.has("data")?(com.fasterxml.jackson.databind.node.ObjectNode)b.get("data").deepCopy():w.object(old.get("data").toString());var previous=w.object(old.get("data").toString());data.put("id",previous.path("id").asLong(id));data.put("title",title);if(status.equals("Published")&&List.of("Course","Project").contains(old.get("kind"))){WorkspaceService.stringArray(data.path("skills"),30);WorkspaceService.text(data,"category",1,100);if(!List.of("Beginner","Intermediate","Advanced").contains(data.path("level").asText()))throw ApiException.error(400,"Choose a valid level.");if(data.path("hours").asInt(0)<1||data.path("hours").asInt()>1000)throw ApiException.error(400,"Choose a duration between 1 and 1000 hours.");if(old.get("kind").equals("Course")){WorkspaceService.stringArray(data.path("lessons"),200);if(data.path("lessons").isEmpty())throw ApiException.error(400,"Add course lessons before publication.");WorkspaceService.text(data,"instructor",2,150);}else WorkspaceService.text(data,"brief",20,10000);}
 db.update("UPDATE content SET title=?,status=?,data=?::jsonb WHERE id=?",title,status,w.encode(data),id);w.audit(SecurityConfig.member(a).id(),"content.update",String.valueOf(id),b);return Map.of("message","Content updated.");}
 @GetMapping("/bookings") Object bookings(){return db.queryForList("SELECT b.*,p.status AS payment_status,p.provider FROM booking b JOIN payment p ON p.booking_id=b.id ORDER BY b.created_at DESC LIMIT 100");}
 @GetMapping("/audit") Object audit(){return db.queryForList("SELECT * FROM audit_event ORDER BY id DESC LIMIT 100");}
 @GetMapping("/reports") Object reports(){return db.queryForList("SELECT * FROM report ORDER BY id DESC LIMIT 100");}
 @PatchMapping("/reports/{id}") Object report(Authentication a,@PathVariable long id,@RequestBody JsonNode b){String decision=WorkspaceService.text(b,"decision",10,2000);if(db.update("UPDATE report SET status='Resolved',decision=?,reviewed_by=? WHERE id=?",decision,SecurityConfig.member(a).id(),id)==0)throw ApiException.error(404,"Report not found.");w.audit(SecurityConfig.member(a).id(),"report.resolve",String.valueOf(id),b);return Map.of("message","Report resolved.");}
 @GetMapping("/overview") Object overview(@RequestParam(defaultValue="30")int days){days=Math.min(365,Math.max(1,days));return Map.of("learners",db.queryForObject("SELECT count(*) FROM app_user WHERE role='LEARNER'",Long.class),"mentors",db.queryForObject("SELECT count(*) FROM mentor_profile WHERE approved",Long.class),"pendingApplications",db.queryForObject("SELECT count(*) FROM mentor_application WHERE status='Pending'",Long.class),"bookings",db.queryForObject("SELECT count(*) FROM booking WHERE created_at>now()-make_interval(days=>?)",Long.class,days),"testRevenue",db.queryForObject("SELECT coalesce(sum(amount),0) FROM payment WHERE status='test_paid' AND created_at>now()-make_interval(days=>?)",Double.class,days),"paymentMode","internal_development_sandbox");}
}
